func compress(chars []byte) int {
	write := 0
	read := 0
	for read < len(chars) {
		ch := chars[read]
		start := read
		for read < len(chars) && chars[read] == ch {
			read++
		}
		count := read - start
		chars[write] = ch
		write++
		if count > 1 {
			for _, digit := range []byte(strconv.Itoa(count)) {
				chars[write] = digit
				write++
			}
		}
	}
	return write
}
